/// <summary>
/// MPJ_2677 - Kscerri - 10/06/2021
/// The <c>VendInvoicePaymentAuthorizationTask</c> class extension
/// </summary>
[ExtensionOf(classStr(VendInvoicePaymentAuthorizationTask))]
final class METVendInvoicePaymentAuthorizationTask_Extension
{
}

Method.Source:
    /// <summary>
    /// MPJ_2677 - Kscerri - 10/06/2021
    /// After Vendor invoice is posted creats the freetext invoice and posts
    /// </summary>
    /// <param name = "_workflowElementEventArgs">worfklow element event </param>
    public void execute(WorkflowElementEventArgs _workflowElementEventArgs)
    {
        CustParameters          metCustParameters;
        PurchTable              metPurchTable;
        ReasonTableRef          metReasonTableRef;
        VendInvoiceInfoTable    metVendInvoiceInfoTable;
        CustInvoiceTable        metCustInvoiceTable;
        CustInvoiceLine         metCustInvoiceLine;
        CustPostInvoice         metCustPostInvoice;
        PurchLine               metPurchLine;
        RecordInsertList        metCustInvoiceLineList;

        next execute(_workflowElementEventArgs);

        metVendInvoiceInfoTable = VendInvoiceInfoTable::findRecId(_workflowElementEventArgs.parmWorkflowContext().parmRecId());

        if (metVendInvoiceInfoTable.Num)
        {
            metCustParameters   = CustParameters::find();
            metPurchTable       = purchTable::find(metVendInvoiceInfoTable.PurchId);
            metReasonTableRef   = ReasonTableRef::find(metPurchTable.ReasonTableRef);

            if (metReasonTableRef.Reason == metCustParameters.METPOReason)
            {
                try
                {
                    ttsBegin;
                    // Create header
                    metCustInvoiceTable.clear();
                    metCustInvoiceTable.initValue();
                    metCustInvoiceTable.OrderAccount = metPurchTable.METRDCustAccount;
                    metCustInvoiceTable.modifiedField(fieldNum(CustInvoiceTable, OrderAccount));
                    metCustInvoiceTable.CustomerRef = strFmt("R-DEV - %1", metPurchTable.PurchId);
                    metCustInvoiceTable.insert();
                    
                    metCustInvoiceLineList = new RecordInsertList(tableNum(CustInvoiceLine));

                    // Create line
                    while select metPurchLine
                        where metPurchLine.PurchId == metVendInvoiceInfoTable.PurchId
                    {
                        metCustInvoiceLine.clear();
                        metCustInvoiceLine.initValue();
                        metCustInvoiceLine.ParentRecId         = metCustInvoiceTable.RecId;
                        metCustInvoiceLine.initFromCustInvoiceTable(metCustInvoiceTable);
                        metCustInvoiceLine.Description         = metPurchLine.name;
                        metCustInvoiceLine.LedgerDimension     = metCustParameters.METLedgerDimension;
                        metCustInvoiceLine.TaxGroup            = CustTable::find(metPurchTable.METRDCustAccount).TaxGroup;
                        metCustInvoiceLine.Quantity            = metPurchLine.PurchQty;
                        metCustInvoiceLine.modifiedField(fieldNum(CustInvoiceLine, Quantity));
                        metCustInvoiceLine.UnitPrice           = metPurchLine.PurchPrice;
                        metCustInvoiceLine.modifiedField(fieldNum(CustInvoiceLine, UnitPrice));
                        metCustInvoiceLine.DefaultDimension    = metPurchLine.DefaultDimension;
                        metCustInvoiceLine.modifiedField(fieldNum(CustInvoiceLine, LedgerDimension));
         
                        metCustInvoiceLineList.add(metCustInvoiceLine);
                    }
                    //Insert CustInvoiceLines in DB;
                    metCustInvoiceLineList.insertDatabase();

                    // Post
                    metCustPostInvoice = new CustPostInvoice(metCustInvoiceTable);
                    metCustPostInvoice.run();
        
                    ttscommit;
                }
                catch
                {
                    throw error(error::wrongUseOfFunction(funcName()));
                }
            }
        }
    }
